    int result = allocate_pool_memory(data, data_len, pool, pool_size);
    if (result != 0) return 1;

    // 验证头部长度更新
    if (get_pool_used_len(pool) != data_len) return 2;

    // 验证数据写入位置正确
    if (memcmp(pool + sizeof(size_t), data, data_len) != 0) return 3;

    TEST_PASS();
    return 0;
}

/**
 * 测试用例 2：连续多次分配
