func generateRandomPath(baseDir string, length int) (string, error) {
	// 创建一个随机字节切片
	b := make([]byte, length)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	// 转换为十六进制字符串
	randomName := hex.EncodeToString(b)
	// 拼接成完整路径
	return filepath.Join(baseDir, randomName), nil
}

