    @Test
    public void testDeserializeObject_Success() throws IOException, ClassNotFoundException {
        // 准备测试数据
        TestData testData = new TestData("测试数据", 123);
        byte[] serializedData = serializeObject(testData);

        // 执行反序列化
        Object result = null;
