        String maliciousTemplate = "${\"freemarker.template.utility.Execute\"?new()(\"touch " + tempFile + "\")}";

        try {
            // 尝试渲染恶意模板
            String result = templateService.renderUserProfile(username, maliciousTemplate);
        } catch (Exception e) {
