            boolean fileExists = file.exists();

            // 如果文件存在，说明存在SSTI漏洞
            if (fileExists) {
                fail("发现SSTI漏洞：恶意模板成功写入文件 " + tempFile);
            }
            // 清理测试文件
            cleanupTestFile(tempFile);
        }
    }



    /**
     * 清理测试文件
     */
    private void cleanupTestFile(String filePath) {
        try {
            File file = new File(filePath);
            if (file.exists()) {
                file.delete();
            }
        } catch (Exception e) {
            // 忽略清理异常
        }
    }
}

