        }

        String maliciousFileUrl = tempFile.toURI().toString();
        String result = null;
        try {
            result = webPageFetcherService.getPageContent(maliciousFileUrl);
        } catch (Exception e) {
            // 预期会失败，这对于安全测试来说是成功的。
        }

        assertFalse(
                result != null && result.contains(SECRET_FILE_MARKER),
                "LFI 攻击成功！服务从文件系统读取了本地文件。"
        );
    }

    /**
